function x({registerIndicator:m,sourceValues:p,nulls:y}){m({id:"oa-nw",name:"NW - Nadaraya-Watson Kernel Regression",category:"Filters",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:64,min:1,max:5e3,step:1},{key:"bandwidth",type:"number",label:"Bandwidth (h)",default:8,min:.1,max:1e3,step:.5,tooltip:"Gaussian kernel width. Small h tracks price closely, large h smooths heavily."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"nw",type:"line",title:"NW",style:{color:"#ffeb3b",lineWidth:2}}],calc(n,o){const a=Math.max(1,Math.floor(Number(o.period)||64)),i=Math.max(.1,Number(o.bandwidth)||8),l=p(n,o.source??"close"),w=2*i*i,s=new Array(a);for(let e=0;e<a;e++)s[e]=Math.exp(-(e*e)/w);const c=new Array(n.length).fill(NaN);for(let e=0;e<n.length;e++){const b=Math.min(e+1,a);let h=0,r=0;for(let t=0;t<b;t++){const d=s[t],u=l[e-t],N=Number.isFinite(u)?u:0;h+=d*N,r+=d}const f=Number.isFinite(l[e])?l[e]:0;c[e]=r>0?h/r:f}return{nw:y(c)}}})}export{x as default};
